#include <stdint.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif



void simpleDelay(uint32_t count) {
	while (count--) {
		__asm__("NOP");
	}
}


int main(void) {

	//Enabling the clock for the GPIO pins
	RCC->AHB1ENR |= (1UL<<8);

	//Set pin 1 to output mode
	GPIOI->MODER |= (1UL<<(1*2));

	//Clear the first bit of OTYPER
	GPIOI->OTYPER &= ~(1UL<<1);

	while(1) {
		GPIOI->BSRR = (1UL<<1);

		simpleDelay(2000000);

		GPIOI->BSRR = (1UL<<(1 + 16));

		simpleDelay(2000000);
	}
}
